def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def isComplete(tree):
    vals, left, right = _links(tree)
    if not vals:
        return True
    order = [0]
    seen_gap = False
    head = 0
    while head < len(order):
        k = order[head]
        head += 1
        for c in (left[k], right[k]):
            if c == -1:
                seen_gap = True
            else:
                if seen_gap:
                    return False
                order.append(c)
    return True
